import { useState } from "react";
import { StyleSheet, Text, TextInput, View } from "react-native";
import type { StyleProp, TextInputProps, TextStyle, ViewStyle } from "react-native";
import { metrics, useTokens } from "../lib/rn-tokens";

export interface TextareaProps extends Omit<TextInputProps, "style" | "multiline"> {
  label: string;
  description?: string;
  error?: string;
  /** Visible lines before the text scrolls. */
  rows?: number;
  /** Style of the field wrapper. */
  style?: StyleProp<ViewStyle>;
  /** Extend the inner, named parts of the textarea: label, control, hint or error. The React Native counterpart of `classNames`. */
  styles?: {
    label?: StyleProp<TextStyle>;
    control?: StyleProp<TextStyle>;
    hint?: StyleProp<TextStyle>;
    error?: StyleProp<TextStyle>;
  };
}

export function Textarea({ label, description, error, rows = 4, editable = true, style, styles: parts, onFocus, onBlur, ...props }: TextareaProps) {
  const tokens = useTokens();
  const [focused, setFocused] = useState(false);
  const disabled = editable === false;
  const border = error ? tokens.danger : focused ? tokens.foreground : tokens.borderStrong;

  return (
    <View style={[local.field, style]}>
      <Text style={[local.label, { color: tokens.foreground }, parts?.label]}>{label}</Text>
      <TextInput
        {...props}
        multiline
        textAlignVertical="top"
        numberOfLines={rows}
        editable={editable}
        accessibilityLabel={props.accessibilityLabel ?? label}
        accessibilityState={{ disabled }}
        accessibilityHint={error ?? description}
        placeholderTextColor={tokens.textMuted}
        onFocus={(event) => {
          setFocused(true);
          onFocus?.(event);
        }}
        onBlur={(event) => {
          setFocused(false);
          onBlur?.(event);
        }}
        style={[
          local.control,
          {
            minHeight: rows * 22 + metrics.space[3] * 2,
            borderColor: border,
            backgroundColor: disabled ? tokens.surfaceMuted : tokens.surface,
            color: tokens.foreground,
            opacity: disabled ? 0.6 : 1,
          },
          parts?.control,
        ]}
      />
      {error ? (
        <Text accessibilityRole="alert" style={[local.message, { color: tokens.danger }, parts?.error]}>
          {error}
        </Text>
      ) : description ? (
        <Text style={[local.message, { color: tokens.textMuted }, parts?.hint]}>{description}</Text>
      ) : null}
    </View>
  );
}

const local = StyleSheet.create({
  field: { alignSelf: "stretch" },
  label: { marginBottom: metrics.space[2], fontSize: metrics.text.sm, fontWeight: "500" },
  control: { borderWidth: 1, borderRadius: metrics.radiusControl, padding: metrics.space[3], fontSize: metrics.text.sm },
  message: { paddingTop: metrics.space[2], fontSize: metrics.text.xs },
});

export default Textarea;

import { useColorScheme } from "react-native";

/** The Manicat UI design tokens as React Native values. Same names and meaning as registry/foundation.css. */
export interface ManicatTokens {
  background: string;
  surface: string;
  surfaceMuted: string;
  foreground: string;
  textSecondary: string;
  textMuted: string;
  border: string;
  borderStrong: string;
  accent: string;
  accentStrong: string;
  accentSubtle: string;
  success: string;
  warning: string;
  danger: string;
  controlOn: string;
  controlTrack: string;
  controlThumb: string;
  controlThumbOn: string;
  /** Four distinguishable colours for chart series, the counterpart of --series-1 to --series-4. */
  series: [string, string, string, string];
}

export const lightTokens: ManicatTokens = {
  background: "#ffffff",
  surface: "#ffffff",
  surfaceMuted: "#f6f6f6",
  foreground: "#1b1b1b",
  textSecondary: "#6e6e6e",
  textMuted: "#8f8f8f",
  border: "#ebebeb",
  borderStrong: "#c9c9c9",
  accent: "#4a4a4a",
  accentStrong: "#303030",
  accentSubtle: "rgba(74, 74, 74, 0.1)",
  success: "#1f8a4c",
  warning: "#b8741a",
  danger: "#d03b3b",
  controlOn: "#2c2c2c",
  controlTrack: "#e2e2e2",
  controlThumb: "#ffffff",
  controlThumbOn: "#ffffff",
  series: ["#1f7dcf", "#7128a5", "#e58f00", "#009e84"],
};

export const darkTokens: ManicatTokens = {
  background: "#2b2b2b",
  surface: "#303030",
  surfaceMuted: "#3c3c3c",
  foreground: "#f1f1f1",
  textSecondary: "#c4c4c4",
  textMuted: "#a0a0a0",
  border: "#454545",
  borderStrong: "#5c5c5c",
  accent: "#cfcfcf",
  accentStrong: "#e6e6e6",
  accentSubtle: "rgba(207, 207, 207, 0.13)",
  success: "#5fd48a",
  warning: "#f0b95c",
  danger: "#ff8a80",
  controlOn: "#ececec",
  controlTrack: "#515151",
  controlThumb: "#f4f4f4",
  controlThumbOn: "#2b2b2b",
  series: ["#55adff", "#9c37be", "#e66e00", "#00a861"],
};

/** Shape and rhythm shared by every component, in density-independent pixels. */
export const metrics = {
  radiusControl: 18,
  radiusPill: 9999,
  controlHeight: { sm: 36, md: 44, lg: 50 },
  space: { 1: 4, 2: 8, 3: 12, 4: 16, 5: 20 },
  text: { xs: 12, sm: 14, lg: 18 },
} as const;

/** The tokens for the device's current colour scheme. Wrap the app in your own provider if you manage the theme yourself. */
export function useTokens(): ManicatTokens {
  return useColorScheme() === "dark" ? darkTokens : lightTokens;
}
